import{_ as a,o as t,c as s,aO as i}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"AdmittanceController 恒力控制二次开发踩坑记","description":"","frontmatter":{"date":"2026-10-29T09:54:00.000Z","title":"AdmittanceController 恒力控制二次开发踩坑记","source":[["1-知识/机器人/ROS2/AdmittanceController恒力控制二次开发踩坑记"]],"tags":["机器人","问题排查","ROS2","力控制"],"categories":["机器人"],"permalink":"/pages/4be631"},"headers":[],"relativePath":"机器人/AdmittanceController 恒力控制二次开发踩坑记.md","filePath":"机器人/AdmittanceController 恒力控制二次开发踩坑记.md","lastUpdated":1793240540000}'),l={name:"机器人/AdmittanceController 恒力控制二次开发踩坑记.md"};function o(d,e,n,r,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="admittancecontroller-恒力控制二次开发踩坑记" tabindex="-1">AdmittanceController 恒力控制二次开发踩坑记 <a class="header-anchor" href="#admittancecontroller-恒力控制二次开发踩坑记" aria-label="Permalink to &quot;AdmittanceController 恒力控制二次开发踩坑记&quot;">​</a></h1> <p>在开源控制器上做二次开发，「写代码」往往只占排查工作量的一小部分：编译产物不同步、进程环境没刷新、插件发现失效，每一层都能把代码层的正确改动掩盖得毫无反应。本文记录在 ros2_controllers（Humble，v2.54.0 / commit <code>2105376</code>）的 AdmittanceController 上做恒力控制二次开发的全过程踩坑：fork 出独立包 <code>admittance_controller_fork</code>（原包只读、保留为 diff 基准），按 TDD 注入期望力参数 <code>desired_wrench</code>，把「零力泄放」的导纳改成恒力控制。坑按排查层次排列：代码、编译产物、进程环境、物理语义，全程在 mock 硬件 + GenericSystem 环境验证。控制器架构背景见<a href="./ros2_control 控制器架构与 chainable 机制.html">本站《ros2_control 控制器架构与 chainable 机制》</a>，源码走查见<a href="./AdmittanceController 源码精读与全流程走查.html">本站《AdmittanceController 源码精读与全流程走查》</a>。</p> <h2 id="一、代码层" tabindex="-1">一、代码层 <a class="header-anchor" href="#一、代码层" aria-label="Permalink to &quot;一、代码层&quot;">​</a></h2> <h3 id="fork-一个-ros2-包要改五处身份" tabindex="-1">fork 一个 ROS2 包要改五处身份 <a class="header-anchor" href="#fork-一个-ros2-包要改五处身份" aria-label="Permalink to &quot;fork 一个 ROS2 包要改五处身份&quot;">​</a></h3> <table tabindex="0"><thead><tr><th>身份</th> <th>在哪</th> <th>改动</th></tr></thead> <tbody><tr><td>包名</td> <td><code>CMakeLists.txt</code> 的 <code>project()</code> + <code>package.xml</code> 的 <code>&lt;name&gt;</code></td> <td><code>admittance_controller_fork</code></td></tr> <tr><td>pluginlib 插件类名</td> <td>plugin xml 的 <code>class name</code>/<code>type</code>，测试与 yaml 以字符串引用</td> <td><code>admittance_controller_fork/AdmittanceController</code></td></tr> <tr><td>C++ namespace</td> <td>所有 <code>.hpp/.cpp</code></td> <td><code>admittance_controller_fork::</code></td></tr> <tr><td>头文件安装路径</td> <td><code>include/&lt;pkg&gt;/</code> 目录 + 所有 <code>#include &quot;&lt;pkg&gt;/...&quot;</code></td> <td><code>include/admittance_controller_fork/</code></td></tr> <tr><td>GPL 参数库</td> <td><code>generate_parameter_library()</code> 首参 + yaml 顶层 key + 生成头 include</td> <td><code>admittance_controller_fork_parameters</code></td></tr></tbody></table> <p>两个细节：</p> <ul><li><code>control_msgs/msg/admittance_controller_state</code> 是消息类型名，长得像包名但属于别人，一个字不能动。</li> <li>GPL yaml 顶层 key 只决定生成代码的 C++ namespace；参数名前缀（<code>admittance.*</code>）来自组名，与顶层 key 无关。fork 之后原有的在线调参命令一个字不用改。</li></ul> <p>GPL 生成头的安装位置由 <code>\${PROJECT_NAME}/\${LIB_NAME}.hpp</code> 拼出，包名一改，源码里 include 生成头的路径必须跟着改。</p> <h3 id="批量替换会误伤「文件引用」" tabindex="-1">批量替换会误伤「文件引用」 <a class="header-anchor" href="#批量替换会误伤「文件引用」" aria-label="Permalink to &quot;批量替换会误伤「文件引用」&quot;">​</a></h3> <p>sed 词边界规则 <code>s/\\badmittance_controller\\b/.../g</code> 把 CMakeLists 里 <code>add_library</code> 引用的源文件 <code>src/admittance_controller.cpp</code> 也替换成了 <code>...fork.cpp</code>，而文件本体按设计保留原名（为了和原包 diff 时同名文件对得上），CMake 报 <code>Cannot find source file</code>。身份标识和文件引用会被同一条规则命中，要么文件跟着改名，要么引用保持原名，两头必须一致。</p> <h3 id="同名文件粘错包" tabindex="-1">同名文件粘错包 <a class="header-anchor" href="#同名文件粘错包" aria-label="Permalink to &quot;同名文件粘错包&quot;">​</a></h3> <p>原包和 fork 的 <code>admittance_rule_impl.hpp</code> 路径只差中间一段，两个编辑器 tab 长得一样，改动粘到了原包。定位三板斧：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%y&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">文</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">件</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 时间戳没动 = 没改过</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;desired_wrench&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 数改动落点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/ros2_controllers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admittance_controller</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 原包纯净度</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>粘错的同时内容本身还有个前缀笔误（<code>admittance_state_.desired_wrench_</code>，成员挂在 rule 上不在 state 上），粘对了包也编不过。</p> <h3 id="断言要落在被测行为上-假红" tabindex="-1">断言要落在被测行为上（假红） <a class="header-anchor" href="#断言要落在被测行为上-假红" aria-label="Permalink to &quot;断言要落在被测行为上（假红）&quot;">​</a></h3> <p>现象：稳态断言读到的 <code>admittance_position</code> 恒为 0，速度稳定在 0.3333，都和 F_des 无关。</p> <p>根因在读源码（<code>admittance_rule_impl.hpp:259-271</code>）：<code>admittance_position</code> 是 FK 算出的相对变换——<code>calculate_link_transform(current_joint_pos)</code> 的结果减 <code>ref_trans_base_ft</code>，不是动力学积分器的状态。测试里 <code>current_joint_pos</code> 从建态起就是零向量没人更新，mock 的 FK 又恒返回单位变换，于是 X 恒为 0，弹簧项 <code>K·X</code> 恒为零（控制律在 impl:292：<code>X_ddot = M⁻¹(F − D·Ẋ − K·X)</code>）。系统退化为恒力对纯阻尼，稳态是匀速不是静止：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v = F / (damping + joint_damping) = 5 / (10 + 5) = 0.3333</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>与实测一位不差。修复：覆盖 mock 的 <code>calculate_link_transform</code>，把积分器状态 <code>state.joint_pos</code> 前三维回灌为末端平移——位置反馈接通，弹簧活过来，「稳态偏移 = 力误差/K」才存在可断言的稳态。</p> <p>上游测试文件里没有任何稳态偏移用例，原因正在于此：稳态依赖位置反馈回路，identity mock 给不了。测试数值「过分干净」（精确解析值）时要警惕两种可能：断言精确命中了目标语义，或者断言根本没落到新代码路径上——先弄清是哪种。</p> <h3 id="参数拉取不在数学内核里" tabindex="-1">参数拉取不在数学内核里 <a class="header-anchor" href="#参数拉取不在数学内核里" aria-label="Permalink to &quot;参数拉取不在数学内核里&quot;">​</a></h3> <p><code>apply_parameters_update()</code> 的周期调用在 <code>AdmittanceRule::update()</code>（controller 每周期的主入口，impl:180）里，且受 <code>enable_parameter_update_without_reactivation</code> 开关控制（默认 true，注意它在 yaml 顶层、不带 <code>admittance.</code> 前缀）；<code>calculate_admittance_rule()</code> 是纯数学内核，不拉参数。测试直调内核时，<code>set_parameter</code> 之后要手动补一次 <code>apply_parameters_update()</code>（Testable 子类 <code>using AdmittanceRule::apply_parameters_update;</code> 提权）。</p> <p>GPL 监听器（生成代码）的更新回调用的是 <code>add_on_set_parameters_callback</code>——同进程内 <code>set_parameter</code> 的调用线程里同步派发，不走 topic、不需要 executor spin。这也是在线调参即时生效的机理。</p> <p>一个隐蔽点：<code>desired_wrench_</code> 成员在被 <code>vec_to_eigen</code> 写过之前是未初始化内存，堆上新页恰好全零，控制律减零等于没减。未初始化成员伪装成默认值靠的是运气，不是保证。</p> <h2 id="二、编译产物层" tabindex="-1">二、编译产物层 <a class="header-anchor" href="#二、编译产物层" aria-label="Permalink to &quot;二、编译产物层&quot;">​</a></h2> <ul><li><code>colcon test</code> 不编译。改了源码必须先 <code>colcon build</code>，否则测试跑的是旧二进制。判断技巧：失败断言报的行号变了说明重编过。</li> <li>测试链接 build 目录的库，controller_manager dlopen install 目录的库，排查时两份都要 <code>stat</code> 对时间。</li> <li>源码里的 <code>config/launch/urdf</code> 是包的数据文件，launch 按<strong>路径</strong>读 install 里的副本。改了实验包的 <code>controllers.yaml</code> 后必须 <code>colcon build --packages-select &lt;实验包&gt;</code>。一次故障里 install 的 yaml 停在旧版，<code>type</code> 还是原插件名，CM 一直加载原包的库。</li></ul> <h2 id="三、进程环境层-其中代价最大的一串" tabindex="-1">三、进程环境层（其中代价最大的一串） <a class="header-anchor" href="#三、进程环境层-其中代价最大的一串" aria-label="Permalink to &quot;三、进程环境层（其中代价最大的一串）&quot;">​</a></h2> <p>「改了代码却毫无反应」的完整病根是三个世界不同步：</p> <ol><li><strong>yaml</strong>：launch 按文件路径读 install 的副本——改源码要 rebuild 数据包；</li> <li><strong>插件库</strong>：CM 启动时 dlopen，build 之后要重启 launch，活着的进程看不见新 <code>.so</code>；</li> <li><strong>插件发现</strong>：pluginlib 扫 <code>$AMENT_PREFIX_PATH</code> 下各前缀的 <code>share/ament_index/resource_index/controller_interface__pluginlib__plugin/&lt;pkg&gt;</code>——环境变量是 shell source 那一刻的快照。isolated install 的 <code>install/setup.zsh</code> 是聚合脚本，build 新包后旧 shell 不会刷新，直接报 <code>Loader for controller &#39;admittance_controller&#39; (type &#39;admittance_controller_fork/AdmittanceController&#39;) not found</code>，而 Available classes 列表里只有原包。</li></ol> <p>排查中两个容易被误导的信号：</p> <ul><li><strong><code>Set parameter successful</code> 没有鉴别力</strong>。CM 给控制器节点的 NodeOptions 开着 <code>automatically_declare_parameters_from_overrides</code>（蕴含 allow_undeclared），set 一个不存在的参数会自动声明并返回成功，值躺在参数树里没有任何消费者。参数 get 得到值同样不构成证据。</li> <li><strong><code>/proc/&lt;pid&gt;/maps</code> 是终极证据</strong>。进程内存里实际映射的 <code>.so</code> 路径一查便知加载了哪个库：</li></ul> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admittance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgrep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros2_control_node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/maps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $6}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>build 新包后的固定配套动作，三件缺一不可：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --packages-select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install/setup.zsh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 每个在用的 shell 都要重新 source</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重启 launch（数据包或插件包有改动时）</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="四、物理语义层" tabindex="-1">四、物理语义层 <a class="header-anchor" href="#四、物理语义层" aria-label="Permalink to &quot;四、物理语义层&quot;">​</a></h2> <ul><li>mock 的 FT 传感器是 URDF <code>initial_value</code> 写死的常数，<code>GenericSystem::read()</code> 每周期原样回放，与臂的位置无关——环境反馈回路不存在，等效环境刚度为 0。</li> <li>因此 mock 里恒力控制的验收标准是<strong>偏移重新平衡</strong>：<code>x* = (F_meas − F_des)/K</code>。力误差恒存不妨碍静止——稳态条件是合力为零，弹簧力 <code>K·x*</code> 顶住误差即可，不需要每个力消失。导纳没有积分器，弹簧就是位移限位，误差再大偏移也封顶在 <code>F_err/K</code>；会一直跑到头的是带积分的控制器（windup）。这是导纳式力控相对积分型力控的安全属性。</li> <li>方向与坐标系：实测力 <code>wrench_base = (−9.13, 0, −4.08) N</code>（base 帧，模长 10 N，沿传感器 −z 的投影）；<code>desired_wrench</code> 表达在 control frame（tool0，与传感器帧平行），同一个力写成 <code>(0, 0, −10)</code>。设参数前先 <code>ros2 topic echo</code> 确认符号，这是真机检查单的第一条。验收：设 <code>[0,0,−10]</code>（与实测同向同值）偏移从 0.1 m 收回 0；设 <code>[0,0,−20]</code> 偏移反向漂 0.1 m。</li></ul> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>fork 包的身份五件套加上同形消息名，动手前一次列全；批量替换同时命中身份标识与文件引用，CMake 的源文件引用单独核对。</li> <li>假测试的两个识别信号：断言读到的量不随被测行为变化（FK 量 vs 积分量）；mock 没有接通被测机制依赖的反馈（弹簧需要位置反馈）。</li> <li>「改了没反应」先查三个世界：源码到 install（rebuild）、install 到进程（重启）、环境到注册表（重新 source）。<code>Set parameter successful</code> 不构成任何证据，<code>/proc/&lt;pid&gt;/maps</code> 才是。</li> <li>mock 验收看偏移平衡，不看力收敛——传感器是死值，环境回路本来就不存在。</li></ul> <p>导纳定律的坐标系关系（六个位姿的来历）见<a href="./AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁.html">本站《AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁》</a>；力控算法层面导纳与 PI 的对比见<a href="./导纳控制与PI控制.html">本站《导纳控制与 PI 控制：力控算法的定位与对比》</a>。</p>`,73)])])}const m=a(l,[["render",o]]);export{k as __pageData,m as default};
